# Generates src/compiler/udpws_runtime.kark from runtime/udpws/c/*.
#
# v1.2.21: the self-hosted compiler embeds the C23 UDP/WebSocket runtime as
# emitLine one-liners. This script is the single implementation of that
# transform - never hand-edit the generated file.
#   powershell -ExecutionPolicy Bypass -File scripts\gen-udpws-runtime.ps1
#
# A Go freshness gate (pkg/codegen TestUDPWSKarkFresh) compares the recorded
# SHA-256 digests with the live sources and fails when they drift.

$ErrorActionPreference = "Stop"
$root = Split-Path -Parent $PSScriptRoot
$srcDir = Join-Path $root "runtime/udpws/c"
$outPath = Join-Path $root "src/compiler/udpws_runtime.kark"

$files = @("karkain_udpws.h", "karkain_udpws.c")

function Escape-KarkString([string]$s) {
    return $s.Replace("\", "\\").Replace('"', '\"')
}

$sb = New-Object System.Text.StringBuilder
[void]$sb.AppendLine("// Generated by scripts/gen-udpws-runtime.ps1 - DO NOT EDIT BY HAND.")
[void]$sb.AppendLine("// v1.2.21: C23 UDP/WebSocket runtime embedded for the self-hosted")
[void]$sb.AppendLine("// backend. Regenerate with: powershell -File scripts/gen-udpws-runtime.ps1")
$digests = @()
foreach ($f in $files) {
    $bytes = [System.IO.File]::ReadAllBytes((Join-Path $srcDir $f))
    $norm = $bytes | Where-Object { $_ -ne 13 }
    $sha = [System.Security.Cryptography.SHA256]::Create()
    $hex = ($sha.ComputeHash($norm) | ForEach-Object { $_.ToString("x2") }) -join ""
    $digests += "$f=$hex"
}
[void]$sb.AppendLine("// runtime-sha256: " + ($digests -join " "))
[void]$sb.AppendLine("")
[void]$sb.AppendLine("// emitUDPWSRuntime appends the C23 UDP/WebSocket runtime.")
[void]$sb.AppendLine("func emitUDPWSRuntime(state) {")

foreach ($f in $files) {
    [void]$sb.AppendLine('    emitLine(state, "// ==== v1.2.21 runtime source: ' + $f + ' ====")')
    $text = [System.IO.File]::ReadAllText((Join-Path $srcDir $f), [System.Text.Encoding]::UTF8)
    foreach ($line in $text -split '\r?\n') {
        $t = $line.Trim()
        if ($t.StartsWith('#include "karkain_udpws.h"')) { continue }
        [void]$sb.AppendLine('    emitLine(state, "' + (Escape-KarkString $line) + '")')
    }
}
[void]$sb.AppendLine("}")

$final = $sb.ToString() -replace '\r(?=\n)', ''
[System.IO.File]::WriteAllText($outPath, $final, (New-Object System.Text.UTF8Encoding $false))
Write-Host "wrote $outPath"
